// One shape for both inputs. MQTT: operator/messages/<channel>. Webhook: the
// body, with its own `channel`. A channel adapter (Telegram, WhatsApp, a web
// chat) sends {conversation, user, text} for a message, or {conversation,
// button} when the operator presses a button of a reply. It reads the replies
// on operator/replies/<channel>.
const fromMqtt = typeof $json.topic === 'string';
const body = fromMqtt ? $json.message : $json.body;
const msg = body && typeof body === 'object' && !Array.isArray(body) ? body : {};
const name = fromMqtt ? $json.topic.split('/')[2] : msg.channel;
const channel = /^[a-z0-9_-]{1,32}$/.test(String(name || '')) ? String(name) : 'unknown';
const conversation = String(msg.conversation ?? '').slice(0, 128);
const button = msg.button && typeof msg.button === 'object' ? msg.button : null;
// The whole message, whitespace collapsed, at most 500 characters
const text = typeof msg.text === 'string' ? msg.text.replace(/\s+/g, ' ').trim().slice(0, 500) : '';

return {
  json: {
    kind: !conversation ? 'invalid' : button ? 'button' : 'message',
    channel,
    conversation,
    user: String(msg.user ?? '').slice(0, 128),
    lang: ['en', 'es'].includes(msg.lang) ? msg.lang : null,
    text,
    button,
  },
};

// ── SITE CONFIG: edit for your site ─────────────────────────────────────────
// Labels for the buttons, per language. The keys must be the options of the
// operator-intake question set (config/system1/questions/operator-intake.json):
// rename the assets in both places.
const INTENTS = {
  report_fault: { en: 'Report a fault', es: 'Reportar una falla' },
  status_request: { en: 'Status request', es: 'Consulta de estado' },
  maintenance_request: { en: 'Maintenance request', es: 'Solicitud de mantenimiento' },
};
const ASSETS = {
  'pump-1': { en: 'Pump 1', es: 'Bomba 1' },
  'pump-2': { en: 'Pump 2', es: 'Bomba 2' },
  'pump-3': { en: 'Pump 3', es: 'Bomba 3' },
  'compressor-1': { en: 'Air compressor', es: 'Compresor' },
  none: { en: 'No specific asset', es: 'Ningún equipo' },
};
// A no-answer key of the set, and the buttons that clarify it
const ASSET_GROUPS = { pump: ['pump-1', 'pump-2', 'pump-3'] };
// Greetings and thanks, per language. A message made only of these (and of
// FILLER words), at most 40 characters, gets a canned reply and never reaches
// System 1, which routes small talk as requests (docs: decisions/system1.md §6.6).
const GREETINGS = {
  en: ['good morning', 'good afternoon', 'good evening', 'hello', 'hi', 'hey', 'bye', 'cheers'],
  es: ['buenos días', 'buenos dias', 'buenas tardes', 'buenas noches', 'buenas', 'hola', 'adiós', 'adios', 'chao', 'saludos'],
};
const THANKS = {
  en: ['thank you', 'thanks', 'thx', 'ok', 'okay', 'great', 'perfect'],
  es: ['muchas gracias', 'gracias', 'vale', 'ok', 'perfecto', 'genial'],
};
const FILLER = ['team', 'all', 'everyone', 'you', 'very', 'much', 'so', 'a', 'todos', 'equipo', 'muy', 'y', 'and'];
const REPLIES = {
  greeting: { en: 'Hello! Tell me about a fault, ask for a status or request maintenance.', es: '¡Hola! Cuénteme de una falla, pida un estado o solicite mantenimiento.' },
  thanks: { en: "You're welcome.", es: 'De nada.' },
  which_intent: { en: 'What do you need?', es: '¿Qué necesita?' },
  which_asset: { en: 'Which equipment is it about?', es: '¿De qué equipo se trata?' },
  confirm: { en: 'Please confirm: {intent} for {asset}.', es: 'Confirme por favor: {intent} para {asset}.' },
  confirmed: { en: 'Sent: {intent} for {asset}.', es: 'Enviado: {intent} para {asset}.' },
  cancelled: { en: 'Cancelled.', es: 'Cancelado.' },
  expired: { en: 'That request has expired. Please send it again.', es: 'Esa solicitud venció. Envíela de nuevo, por favor.' },
  confirm_button: { en: 'Confirm', es: 'Confirmar' },
  change_intent: { en: 'Change the request', es: 'Cambiar la solicitud' },
  change_asset: { en: 'Change the equipment', es: 'Cambiar el equipo' },
  cancel_button: { en: 'Cancel', es: 'Cancelar' },
};
// Drafts not confirmed within this time are dropped
const DRAFT_TTL_MS = 30 * 60 * 1000;
// Opt-in: also send the message text with each confirmation on
// system1/feedback/operator-intake, so it can become an evaluation example
// (p4n4 ai system1 feedback). Messages can hold personal data: off by default.
const FEEDBACK_STATES = false;
// ─────────────────────────────────────────────────────────────────────────────

const SET = 'operator-intake';
const CALLER = 'n8n-operator-intake';
const FIELDS = ['intent', 'asset'];
const LABELS = { intent: INTENTS, asset: ASSETS };

function guessLang(text) {
  const words = text.toLowerCase().match(/[a-záéíóúñü]+/g) || [];
  const es = new Set(['el', 'la', 'los', 'las', 'de', 'del', 'que', 'por', 'para', 'una', 'un', 'hay', 'está', 'esta', 'no', 'se', 'bomba', 'compresor', 'necesitamos', 'gracias', 'hola', 'buenos', 'buenas']);
  const hits = words.filter(w => es.has(w)).length;
  return hits > 0 && hits * 4 >= words.length || /[¿¡ñ]/.test(text) ? 'es' : 'en';
}
function t(key, lang, vars = {}) {
  const s = REPLIES[key][lang] || REPLIES[key].en;
  return s.replace(/\{(\w+)\}/g, (_, k) => vars[k] ?? '');
}
function label(field, key, lang) {
  const l = LABELS[field][key];
  return l ? l[lang] || l.en : key;
}
function reply(ctx, text, buttons = []) {
  return {
    topic: `operator/replies/${ctx.channel}`,
    message: { conversation: ctx.conversation, ts: new Date().toISOString(), text, buttons },
  };
}
function button(text, data) {
  return { label: text, data };
}
// The next reply for a draft: ask for the first field still missing, or ask to confirm
function prompt(draft) {
  const lang = draft.lang;
  const cancel = button(t('cancel_button', lang), { draft: draft.id, action: 'cancel' });
  if (!draft.fields.intent) {
    return reply(draft, t('which_intent', lang), [
      ...Object.keys(INTENTS).map(k => button(label('intent', k, lang), { draft: draft.id, action: 'set', field: 'intent', value: k })),
      cancel,
    ]);
  }
  if (!draft.fields.asset) {
    const keys = ASSET_GROUPS[draft.asset_hint] || Object.keys(ASSETS);
    return reply(draft, t('which_asset', lang), [
      ...keys.map(k => button(label('asset', k, lang), { draft: draft.id, action: 'set', field: 'asset', value: k })),
      cancel,
    ]);
  }
  const vars = { intent: label('intent', draft.fields.intent, lang), asset: label('asset', draft.fields.asset, lang) };
  return reply(draft, t('confirm', lang, vars), [
    button(t('confirm_button', lang), { draft: draft.id, action: 'confirm' }),
    button(t('change_intent', lang), { draft: draft.id, action: 'change', field: 'intent' }),
    button(t('change_asset', lang), { draft: draft.id, action: 'change', field: 'asset' }),
    cancel,
  ]);
}

// Drafts wait in the workflow's static data, which n8n keeps for active
// (production) executions only
const store = $getWorkflowStaticData('global');
store.drafts = store.drafts || {};
const now = Date.now();
for (const [id, d] of Object.entries(store.drafts)) {
  if (now - d.created > DRAFT_TTL_MS) delete store.drafts[id];
}

const m = $json;
const out = { ...m, ask_system1: false, publish: [] };

if (m.kind === 'invalid') return { json: out };

if (m.kind === 'button') {
  const b = m.button;
  const draft = store.drafts[String(b.draft || '')];
  const lang = draft ? draft.lang : m.lang || 'en';
  if (!draft || draft.conversation !== m.conversation) {
    out.publish.push(reply(m, t('expired', lang)));
    return { json: out };
  }
  if (b.action === 'cancel') {
    delete store.drafts[draft.id];
    out.publish.push(reply(draft, t('cancelled', lang)));
  } else if (b.action === 'change' && FIELDS.includes(b.field)) {
    draft.fields[b.field] = null;
    draft.asset_hint = null;
    out.publish.push(prompt(draft));
  } else if (b.action === 'set' && FIELDS.includes(b.field) && b.value in LABELS[b.field]) {
    draft.fields[b.field] = b.value;
    draft.by_operator[b.field] = true;
    out.publish.push(prompt(draft));
  } else if (b.action === 'confirm' && draft.fields.intent && draft.fields.asset) {
    delete store.drafts[draft.id];
    const f = draft.fields;
    out.publish.push({
      topic: `operator/requests/${f.intent}`,
      message: {
        id: draft.id,
        ts: new Date().toISOString(),
        intent: f.intent,
        asset: f.asset,
        text: draft.text,
        channel: draft.channel,
        conversation: draft.conversation,
        user: draft.user,
        // Which fields System 1 suggested and the operator kept
        suggested: Object.fromEntries(FIELDS.map(k => [k, !draft.by_operator[k]])),
      },
    });
    // What the operator confirmed, for each question System 1 answered: the
    // dashboard's agreement rate, and evaluation examples when FEEDBACK_STATES
    if (draft.decision) {
      for (const q of FIELDS) {
        const a = draft.decision.answers[q];
        if (!a) continue;
        out.publish.push({
          topic: `system1/feedback/${SET}`,
          message: {
            id: draft.id,
            ts: new Date().toISOString(),
            set: SET,
            set_version: draft.decision.set_version,
            caller: CALLER,
            question: q,
            expected: f[q],
            choice: a.choice,
            abstain: a.abstain,
            lang: draft.lang,
            ...(FEEDBACK_STATES ? { state: { text: draft.text } } : {}),
          },
        });
      }
    }
    out.publish.push(reply(draft, t('confirmed', lang, { intent: label('intent', f.intent, lang), asset: label('asset', f.asset, lang) })));
  } else {
    out.publish.push(prompt(draft));
  }
  return { json: out };
}

// A message. Rules first: empty messages and stickers get nothing, greetings
// and thanks a canned reply, and only the rest reaches System 1.
const lang = m.lang || guessLang(m.text);
out.lang = lang;
const plain = m.text.toLowerCase().replace(/[^\p{L}\p{N}\s]/gu, ' ').replace(/\s+/g, ' ').trim();
if (!plain) return { json: out };
if (plain.length <= 40) {
  let rest = ' ' + plain + ' ';
  const phrases = [...GREETINGS.en, ...GREETINGS.es, ...THANKS.en, ...THANKS.es, ...FILLER]
    .sort((a, b) => b.length - a.length);
  for (const p of phrases) rest = rest.split(' ' + p + ' ').join(' ');
  if (!rest.trim()) {
    const thanks = [...THANKS.en, ...THANKS.es].some(p => (' ' + plain + ' ').includes(' ' + p + ' '));
    out.publish.push(reply({ ...m, lang }, t(thanks ? 'thanks' : 'greeting', lang)));
    return { json: out };
  }
}
out.ask_system1 = true;
out.asked_at = Date.now();
out.config = { INTENTS, ASSETS, ASSET_GROUPS, REPLIES, no_answer: { intent: ['other'], asset: Object.keys(ASSET_GROUPS) } };
return { json: out };

function uuid() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = Math.random() * 16 | 0;
    return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
  });
}

// The site config is edited in Intake Rules, which hands it on
const m = $('Intake Rules').item.json;
const { INTENTS, ASSETS, ASSET_GROUPS, REPLIES } = m.config;

const SET = 'operator-intake';
const CALLER = 'n8n-operator-intake';
const FIELDS = ['intent', 'asset'];
const LABELS = { intent: INTENTS, asset: ASSETS };

function guessLang(text) {
  const words = text.toLowerCase().match(/[a-záéíóúñü]+/g) || [];
  const es = new Set(['el', 'la', 'los', 'las', 'de', 'del', 'que', 'por', 'para', 'una', 'un', 'hay', 'está', 'esta', 'no', 'se', 'bomba', 'compresor', 'necesitamos', 'gracias', 'hola', 'buenos', 'buenas']);
  const hits = words.filter(w => es.has(w)).length;
  return hits > 0 && hits * 4 >= words.length || /[¿¡ñ]/.test(text) ? 'es' : 'en';
}
function t(key, lang, vars = {}) {
  const s = REPLIES[key][lang] || REPLIES[key].en;
  return s.replace(/\{(\w+)\}/g, (_, k) => vars[k] ?? '');
}
function label(field, key, lang) {
  const l = LABELS[field][key];
  return l ? l[lang] || l.en : key;
}
function reply(ctx, text, buttons = []) {
  return {
    topic: `operator/replies/${ctx.channel}`,
    message: { conversation: ctx.conversation, ts: new Date().toISOString(), text, buttons },
  };
}
function button(text, data) {
  return { label: text, data };
}
// The next reply for a draft: ask for the first field still missing, or ask to confirm
function prompt(draft) {
  const lang = draft.lang;
  const cancel = button(t('cancel_button', lang), { draft: draft.id, action: 'cancel' });
  if (!draft.fields.intent) {
    return reply(draft, t('which_intent', lang), [
      ...Object.keys(INTENTS).map(k => button(label('intent', k, lang), { draft: draft.id, action: 'set', field: 'intent', value: k })),
      cancel,
    ]);
  }
  if (!draft.fields.asset) {
    const keys = ASSET_GROUPS[draft.asset_hint] || Object.keys(ASSETS);
    return reply(draft, t('which_asset', lang), [
      ...keys.map(k => button(label('asset', k, lang), { draft: draft.id, action: 'set', field: 'asset', value: k })),
      cancel,
    ]);
  }
  const vars = { intent: label('intent', draft.fields.intent, lang), asset: label('asset', draft.fields.asset, lang) };
  return reply(draft, t('confirm', lang, vars), [
    button(t('confirm_button', lang), { draft: draft.id, action: 'confirm' }),
    button(t('change_intent', lang), { draft: draft.id, action: 'change', field: 'intent' }),
    button(t('change_asset', lang), { draft: draft.id, action: 'change', field: 'asset' }),
    cancel,
  ]);
}

// System 1 suggests the request type and the asset. A suggestion is kept only
// when it clears the set's threshold and isn't a no-answer key; anything
// missing is asked with buttons, and every draft needs the operator's
// confirmation (docs: decisions/system1.md §6.6). On an error, a timeout or a
// 4xx the operator gets the buttons for everything.
const store = $getWorkflowStaticData('global');
store.drafts = store.drafts || {};
const res = $json;
const ok = res && res.answers && res.set;
const id = uuid();
const draft = {
  id,
  created: Date.now(),
  channel: m.channel,
  conversation: m.conversation,
  user: m.user,
  lang: m.lang,
  text: m.text,
  fields: { intent: null, asset: null },
  by_operator: {},
  asset_hint: null,
  decision: null,
};
const publish = [];
if (ok) {
  for (const q of FIELDS) {
    const a = res.answers[q];
    if (!a) continue;
    if (!a.abstain && !m.config.no_answer[q].includes(a.choice) && a.choice in LABELS[q]) draft.fields[q] = a.choice;
  }
  const asset = res.answers.asset;
  if (asset && asset.choice in ASSET_GROUPS) draft.asset_hint = asset.choice;
  const snapshot = /\/snapshots\/([0-9a-f]{40})/.exec((res.routing || {}).repo || '');
  draft.decision = {
    id,
    ts: new Date().toISOString(),
    set: res.set.name,
    set_version: res.set.version,
    checkpoint: (res.routing || {}).model || '',
    revision: snapshot ? snapshot[1].slice(0, 12) : '',
    caller: CALLER,
    subject: m.channel,
    state_sha256: res.state_sha256 || '',
    latency_ms: Date.now() - m.asked_at,
    answers: Object.fromEntries(Object.entries(res.answers).map(([q, a]) => [q, { choice: a.choice, confidence: a.confidence, abstain: a.abstain }])),
    used: FIELDS.some(q => draft.fields[q]),
  };
  publish.push({ topic: `system1/decisions/${SET}`, message: draft.decision });
}
store.drafts[id] = draft;
publish.push(prompt(draft));
return {
  json: {
    channel: m.channel,
    conversation: m.conversation,
    draft: id,
    system1: ok ? { asked: true, used: draft.decision.used } : { asked: true, used: false, error: String((res.error || {}).message || 'request failed').slice(0, 200) },
    publish,
  },
};
